import {esc as e,fmt as f} from './lib.js?v=20261031-player6';

export function methodView(){
 return `<section class="panel"><div class="panel-body prose"><h2>一条成绩怎么产生</h2><ol><li><strong>先固定题目和评分契约。</strong>保存完整输入、答案、容差、格式要求及逐项评分标准；请求中只发送题目，不发送参考答案。</li><li><strong>按同一配置采集。</strong>记录服务商、模型别名、输出上限、地区、并发、缓存和采集批次。当前运行器串行；模型产品、Agent和纯API不是同一评测对象。</li><li><strong>记录流式事件。</strong>从请求发出开始计时，保存正文分块、用量和结束状态。原始事件留在本机，网页加载经过白名单处理的公开文件。</li><li><strong>分别判内容、格式和合格交付。</strong>自动题重算答案；人工题按每项零、半、满分和文字证据复核，未评保持待评。请求失败不自动获得内容分。</li><li><strong>重放与展示。</strong>本机审计重新拼接正文、核对题目哈希、请求型号及上限，重算评分、计时和费用。导入校验通过只说明结构一致，不能证明来源真实。</li></ol><p>本轮费用上限为0，实际新增请求全部指向本机模拟服务。24题×3个预设输出配置共72次模拟，用于验收系统；新题库尚无真实模型成绩。历史90条实测保留旧协议与旧判分。</p></div></section>
 <section class="panel"><div class="panel-body prose"><h2>速度的几种口径</h2><ul><li><strong>TTFT：</strong>请求开始到第一个非空正文或推理内容事件；忽略角色和元数据。这是客户端事件等待，不是服务端逐token解码计时。</li><li><strong>首正文等待 TTFA：</strong>到第一段正式答案，包含此前推理的等待。</li><li><strong>完整耗时：</strong>到响应结束；失败、超时、截断另列，成功耗时不把失败填成0。</li><li><strong>新协议正文TPS：</strong>（可见总token − 首个正文块token）÷ 首末正文块时间差。至少3块、0.5秒、首块之后64个token；计数或推理分账不可靠时留空。当前真实适配器没有可靠首块token计数，因此不会凭总用量补出新TPS。</li><li><strong>端到端正文TPS：</strong>可见正文token ÷ 完整耗时，包含等待；必须具备可靠可见用量。与正文生成区间TPS分别展示。</li><li><strong>字符/秒：</strong>排除首块后的Unicode字符数 ÷ 正文区间，至少64个后续字符及同样的时间门槛。字符包括标点、空格和英文，不等于token。</li><li><strong>分块间隔：</strong>SSE正文块之间的时间间隔；分块可能包含多个token，不将它命名为ITL。</li></ul><p>例：0秒请求、1秒首内容、2秒首正文、4秒最后正文、5秒结束；可见token共150，首块30。正文TPS=(150−30)/(4−2)=60；端到端TPS=150/5=30；TTFT=1秒、TTFA=2秒、完整耗时=5秒。这些是假设数字。</p><p>中位数同时展示有效样本数。核心P95只在同一批次、同题、同配置的成功样本达到100时展示；这个门槛是本站发布规则，不代表得到服务承诺。单请求速率不能推出并发吞吐。</p><details><summary>历史SSE v2的区别</summary><p>旧TPS用可见总token除以首末正文块时间差，分子包含首块；门槛为3块、0.5秒、总可见64token。它存在边界和缓冲误差，保留为“旧TPS边界估计”，不与新协议合并。旧评分只记录整题通过/失败，不能倒填新内容分和格式分。</p></details></div></section>
 <section class="panel"><div class="panel-body prose"><h2>评分、汇总与费用</h2><p><strong>内容分：</strong>数值按有理数或明确容差比较；结构化答案按字段、值和类型比较。只识别一个明确数值候选，JSON可诊断单层代码围栏中的内容，但格式仍判失败。JSON重复键、非有限数值不接受。每题先平均重复，再对同一题族平均，最后题族等权。</p><p><strong>格式与约束：</strong>格式全满足率看整次是否满足格式及所有机械约束；细项满足率看约束逐项是否满足。纯格式题不冒充知识正确性。人工题的内容与合格结论必须等待逐项复核。</p><p><strong>自动题合格交付：</strong>同一道自动题中，内容及格式都满足的成功次数÷所有已发出的尝试，包括错误、超时、截断；再按题、题族等权。内容分只描述已评输出，两者应一起读。</p><p><strong>合格结果费用：</strong>当前范围所有已发送尝试的费用总和÷合格结果数。费用缺失、有待评或没有合格结果时不给确定值；失败产生的已知费用保留。使用当次报价与用量估算，不等于实际账单。</p><p><strong>重复一致性：</strong>同批次、同题、同repeatIndex中的重试归为一个重复单元；稳定错答不代表能力强。独立题数、题族数和重复次数分别列出，少量重复不扩充独立样本。</p></div></section>
 <section class="panel"><div class="panel-body prose"><h2>现在能说明什么</h2><p>本站核心题库是24题试点，18题自动检查、6题人工复核。参考benchmark的评测思路，不声称复现官方测试或可与官方榜单换算。题目难度与区分度尚未真实校准，不提供综合智力排名。</p><p>代码题缺少已验证的隔离执行环境，不发布pass@1；鹈鹕SVG的静态检查只判断受限格式，视觉正确性仍需人工看图。长材料题尚未构成长上下文长度扫描。并发、工具、视觉理解、音频和安全基准等未接入项在体系表单列。</p><p>选型比较应控制任务、地区、端点、输入输出长度、推理档位、缓存和时间；价格、规格与历史接入状态均不能代替本轮实测。</p><p><a href="#system">查看逐项指标、参考benchmark和实现状态 ↗</a>　<a href="#workflow">查看可执行的本机流程 ↗</a></p></div></section>`;
}

export function measurementView(run){
 const m=run.measurement;if(!m)return '';
 const names={measured:'满足采样门槛',request_incomplete:'请求未完整返回',unknown_tokens:'缺少可靠可见token用量',unknown_first_chunk:'缺少可靠首块token计数',insufficient_sample:'分块、时长或输出长度不足'};
 const fields=[['测量协议',m.protocolId],['正文TPS',f(m.bodyTps)],['正文TPS状态',names[m.bodyTpsState]||m.bodyTpsState],['端到端正文TPS',f(m.endToEndTps)],['可见正文token',f(m.visibleTokens,0)],['首块token',f(m.firstChunkTokens,0)],['正文块数',f(m.chunkCount,0)],['首末正文区间',f(m.sampleSeconds,3)+' s'],['分块间隔 P50 / P95',f(m.chunkGapP50Ms,2)+' / '+f(m.chunkGapP95Ms,2)+' ms']];
 return `<section class="panel"><div class="panel-head"><h2>本次测速依据</h2></div><div class="panel-body"><dl class="facts">${fields.map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl><p class="evidence-meta">分块间隔不是逐token间隔。模拟数据使用玩具字符计数器；真实请求缺失计数时留空。<a href="#method">查看公式和门槛</a></p></div></section>`;
}
